import{H as e,V as t,et as n,j as r}from"./chunks/framework.DCJECfJ5.js";var i=JSON.parse(`{"title":"关于我","description":"","frontmatter":{},"headers":[],"relativePath":"about/Me.md","filePath":"about/Me.md"}`),a={name:`about/Me.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to “关于我”">​</a></h1><p>你好，我是 Quinn。</p><p>一名前端工程师，目前专注于 Web 开发与全栈技术探索。</p><p>我曾经主要使用 Vue 进行前端开发，负责构建用户界面、业务系统以及提升前端工程效率。随着对软件开发的深入理解，我开始探索前端之外的领域，包括 Node.js、数据库、服务端架构以及 AI 应用开发，希望逐渐从一个前端开发者成长为具备完整系统视角的全栈工程师。</p><p>这个网站是我的个人技术实验室（Quinn Lab）。</p><p>这里记录：</p><ul><li>前端技术：JavaScript、TypeScript、Vue、浏览器原理、工程化实践</li><li>后端探索：Node.js、NestJS、API 设计与服务端开发</li><li>数据库学习：SQL、数据建模、数据库设计</li><li>AI 实验：大模型应用、智能工具与未来技术探索</li><li>项目实践：记录自己的想法、作品和开发过程</li></ul><p>我相信，技术成长不仅来自于学习新的工具，更来自于持续思考、实践和总结。</p><p>Quinn Lab 记录的不是一个终点，而是一段持续构建和探索的过程。</p><p>希望这里能够留下我学习、创造和成长的轨迹。</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};